inline Result<Note, EntityError> Note::from_compact_row(Memory r, CompactRow row) {
    using Outcome = Result<Note, EntityError>;
    Note result(std::allocator_arg, Allocator(r));
    auto captured =
        detail::EntityRuntimeAccess::capture_dynamic_values(result.dynamic, row, field_layout(r));
    if (!captured) {
        return Outcome::err(r, std::move(captured).error());
    }
    ArenaBorrow<FieldLayout> field_layout_binding(
        std::allocator_arg, Allocator(r), field_layout(r));
    auto id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "id", "id", false, field_layout_binding);
    if (!id_lookup) {
        return Outcome::err(r, std::move(id_lookup).error());
    }
    auto name_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "name", "name", false, field_layout_binding);
    if (!name_lookup) {
        return Outcome::err(r, std::move(name_lookup).error());
    }
    auto tenant_id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "tenant_id", "tenant", true, field_layout_binding);
    if (!tenant_id_lookup) {
        return Outcome::err(r, std::move(tenant_id_lookup).error());
    }
    auto created_at_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "created_at", "created_at", false, field_layout_binding);
    if (!created_at_lookup) {
        return Outcome::err(r, std::move(created_at_lookup).error());
    }
    auto updated_at_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "updated_at", "updated_at", false, field_layout_binding);
    if (!updated_at_lookup) {
        return Outcome::err(r, std::move(updated_at_lookup).error());
    }
    auto version_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "version", "version", false, field_layout_binding);
    if (!version_lookup) {
        return Outcome::err(r, std::move(version_lookup).error());
    }
    auto id_value =
        generated_detail::decode<std::uint64_t>(r, id_lookup.value().value, ENTITY_NAME, "id");
    if (!id_value) {
        return Outcome::err(r, std::move(id_value).error());
    }
    result.id_ = std::move(id_value).value();
    auto name_value =
        generated_detail::decode<String>(r, name_lookup.value().value, ENTITY_NAME, "name");
    if (!name_value) {
        return Outcome::err(r, std::move(name_value).error());
    }
    result.name_ = std::move(name_value).value();
    auto tenant_id_value = generated_detail::decode<std::uint64_t>(
        r, tenant_id_lookup.value().value, ENTITY_NAME, "tenant_id");
    if (!tenant_id_value) {
        return Outcome::err(r, std::move(tenant_id_value).error());
    }
    result.tenant_id_ = std::move(tenant_id_value).value();
    auto created_at_value = generated_detail::decode<Timestamp>(
        r, created_at_lookup.value().value, ENTITY_NAME, "created_at");
    if (!created_at_value) {
        return Outcome::err(r, std::move(created_at_value).error());
    }
    result.created_at_ = std::move(created_at_value).value();
    auto updated_at_value = generated_detail::decode<Timestamp>(
        r, updated_at_lookup.value().value, ENTITY_NAME, "updated_at");
    if (!updated_at_value) {
        return Outcome::err(r, std::move(updated_at_value).error());
    }
    result.updated_at_ = std::move(updated_at_value).value();
    auto version_value = generated_detail::decode<std::int64_t>(
        r, version_lookup.value().value, ENTITY_NAME, "version");
    if (!version_value) {
        return Outcome::err(r, std::move(version_value).error());
    }
    result.version_ = std::move(version_value).value();
    auto tenant_decoded = GeneratedRelationAccess::decodeObject<Tenant>(r, row.get("tenant"));
    if (!tenant_decoded) {
        return Outcome::err(r, std::move(tenant_decoded).error());
    }
    if (tenant_decoded.value()) {
        result.tenant_ = detail::make_box<Tenant>(r, std::move(*tenant_decoded.value()));
    }
    result.load_state = row.indexed_load_state(
        detail::ContextArena::from_memory(r).loaded_snapshots(), field_layout(r));
    if (tenant_id_lookup.value().alias_present) {
        auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();
        if (!tenant_id_lookup.value().object_alias && !row.is_loaded_relation("tenant")) {
            result.load_state.mark_unloaded("tenant", &pool).value();
        }
        result.load_state.mark_loaded("tenant_id", &pool).value();
    }
    result.root.set_original_compact_row(ENTITY_NAME, row);
    return Outcome::ok(r, std::move(result));
}

inline MutationValues Note::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("tenant_id", r), generated_detail::encode(r, tenant_id_));
    values.fields.emplace(String("created_at", r), generated_detail::encode(r, created_at_));
    values.fields.emplace(String("updated_at", r), generated_detail::encode(r, updated_at_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (tenant_) {
        values.fields.emplace(String("tenant", r),
                              Value(r, std::move(*tenant_).into_values().fields));
    }
    inject_runtime(values);
    return values;
}

inline Note& Note::updateTenant(const Tenant& value) {
    tenant_ = detail::make_box<Tenant>(memory_resource(), value);
    updateTenantId(value.id());
    return *this;
}
